do $$declare mid uuid;iid uuid;begin
 select id into strict mid from email_messages where tenant_id='eb190660-aaaa-4000-8000-000000000001' and provider='microsoft_365' and subject='Synthetic Microsoft job enquiry' and direction='inbound' and body_text='Synthetic message for rollback only' and raw_payload->'microsoft_source'->>'last_modified'='2026-10-11T10:01:00.1234561Z';
 select id into strict iid from interactions where tenant_id='eb190660-aaaa-4000-8000-000000000001' and source_table='email_messages' and source_id=mid and source_connector_id='microsoft-365' and processing_status='pending' and to_addresses=array['synthetic@example.invalid'];
